<?php echo form_open(get_uri('fiscal/client-profiles/save'),['id'=>'fiscal-profile-form','class'=>'general-form']); ?><div class="modal-body"><input type="hidden" name="id" value="<?php echo $model_info->id; ?>"><input type="hidden" name="client_id" value="<?php echo $client_id; ?>"><?php $inputs=[['rfc','RFC'],['legal_name',app_lang('legal_name')],['fiscal_postal_code',app_lang('fiscal_postal_code')],['tax_residency_country',app_lang('tax_residency_country')],['foreign_tax_registration',app_lang('foreign_tax_registration')]]; foreach($inputs as $f){?><div class="form-group row"><label class="col-md-3"><?php echo $f[1]; ?></label><div class="col-md-9"><?php echo form_input(['name'=>$f[0],'value'=>$model_info->{$f[0]},'class'=>'form-control']); ?></div></div><?php } ?><div class="form-group row"><label class="col-md-3"><?php echo app_lang('tax_regime'); ?></label><div class="col-md-9"><?php echo form_dropdown('tax_regime_id',$regimes,$model_info->tax_regime_id,"class='select2 form-control'"); ?></div></div><div class="form-group row"><label class="col-md-3"><?php echo app_lang('default_cfdi_use'); ?></label><div class="col-md-9"><?php echo form_dropdown('default_cfdi_use_id',$uses,$model_info->default_cfdi_use_id,"class='select2 form-control'"); ?></div></div><div class="form-group row"><label class="col-md-3"><?php echo app_lang('status'); ?></label><div class="col-md-9"><?php echo form_dropdown('status',['draft'=>app_lang('fiscal_profile_draft'),'incomplete'=>app_lang('fiscal_profile_incomplete'),'ready'=>app_lang('fiscal_profile_ready'),'inactive'=>app_lang('fiscal_profile_inactive')],$model_info->status?:'draft',"class='select2 form-control'"); ?></div></div><div class="form-group row"><label class="col-md-3"><?php echo app_lang('default'); ?></label><div class="col-md-9"><?php echo form_checkbox('is_default','1',(bool)$model_info->is_default,"class='form-check-input'"); ?></div></div><p class="text-muted"><?php echo app_lang('rfc_format_not_sat_validation'); ?></p></div><div class="modal-footer"><button class="btn btn-default" data-bs-dismiss="modal" type="button"><?php echo app_lang('close'); ?></button><button class="btn btn-primary" type="submit"><?php echo app_lang('save'); ?></button></div><?php echo form_close(); ?><script>$(document).ready(function(){$('#fiscal-profile-form').appForm({onSuccess:function(){location.reload();}});$('.select2').select2();});</script>
